"""Generate reference-grounded whole-body poses; installed skill owns retries."""
from pathlib import Path
import argparse,json,subprocess,sys
R=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--start',type=int,default=117);p.add_argument('--end',type=int,default=126);p.add_argument('--version',type=int,default=1);a=p.parse_args()
assert 117<=a.start<=a.end<=126 and a.version>0
state=R/'assets/animation-generation-117-126.json'
